from selenium.webdriver.common.by import By
from taf.selenium.nms.nom.pages.LoginPage import NomLoginPage


class ConfirmationModal(NomLoginPage):
    _MODAL_LOAD_XPATH = '//div[@class="ccfk-alert-dialog"][@data-test="ccfk-dialog"]'

    def confirm(self):
        """
        Clicks confirm button in selenium_coam confirmation modal
        """
        pass

    def cancel(self):
        """
        Clicks cancel button in selenium_coam confirmation modal
        """
        pass

    def wait_until_modal_appear(self, locator, timeout=60):
        self.wait_for_visibility(locator, timeout)


class AlarmUploadModal(ConfirmationModal):
    _CANCEL_ALARM_UPLOAD = '//div[@data-test="alarmUpload-dialog-footer"]//button[1]'
    _CONFIRM_ALARM_UPLOAD = '//div[@data-test="alarmUpload-dialog-footer"]//button[2]'

    def wait_until_alarm_upload_modal_appear(self, timeout=60):
        self.wait_until_modal_appear((By.XPATH, self._MODAL_LOAD_XPATH), timeout)

    def confirm_alarm_upload(self, timeout=60):
        self.click_enabled_element((By.XPATH, self._CONFIRM_ALARM_UPLOAD), timeout)

    def cancel_alarm_upload(self, timeout=60):
        self.click_enabled_element((By.XPATH, self._CANCEL_ALARM_UPLOAD), timeout)


